    var tb = tables[t];
    var flat = tb.flat instanceof Float64Array ? tb.flat : new Float64Array(tb.flat);
    writeOneTableInPlaceWorker(currentDestFile, tb.name, tb.fields, flat, tb.rowCount, tb.colCount, tb.dtype);
